// ================== CONFIG ==================
var COLUNAS_CODIGO = ["codigo", "vendedor"];   // cabeçalhos aceitos para a coluna do código na planilha
var META_INICIAL = 0;                          // meta das linhas novas
// ==============================================

function pegarRegistros(nodeJson) {
  if (!nodeJson) return [];
  if (!nodeJson.dados) return [];
  if (!Array.isArray(nodeJson.dados) || nodeJson.dados.length === 0) return [];
  var bloco = nodeJson.dados[0];
  if (!bloco || !Array.isArray(bloco.dados)) return [];
  return bloco.dados;
}

// Nomes vindos do ERP às vezes chegam com entidades HTML (ex.: "BEBIDAS &amp; ALIMENTOS").
function decodificarEntidadesHtml(texto) {
  if (texto === null || texto === undefined) return "";
  return String(texto)
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, "\"")
    .replace(/&#39;/g, "'")
    .replace(/&apos;/g, "'");
}

// Compara códigos sem diferenciar "12", " 12 " e "12.0"
function chaveCodigo(valor) {
  if (valor === null || valor === undefined) return "";
  var texto = String(valor).trim();
  if (texto === "") return "";
  if (/^-?\d+(\.\d+)?$/.test(texto)) {
    var numero = Number(texto);
    if (!isNaN(numero)) return String(numero);
  }
  return texto.toUpperCase();
}

// Códigos que JÁ estão na planilha (a leitura vem do node Planilha Atual, intervalo A1:Z)
var valores = $node["Planilha Atual"].json.values;
if (!Array.isArray(valores)) valores = [];

var jaNaPlanilha = {};
if (valores.length > 0) {
  var cabecalho = valores[0].map(function (c) { return String(c).trim().toLowerCase(); });
  var indice = -1;
  for (var i = 0; i < COLUNAS_CODIGO.length && indice < 0; i++) {
    indice = cabecalho.indexOf(COLUNAS_CODIGO[i]);
  }
  if (indice < 0) {
    throw new Error("Não achei a coluna do código (" + COLUNAS_CODIGO.join(" ou ") + ") na linha 1 da planilha. Nada foi alterado.");
  }
  for (var r = 1; r < valores.length; r++) {
    var chave = chaveCodigo(valores[r][indice]);
    if (chave !== "") jaNaPlanilha[chave] = true;
  }
}

// Só entram vendedores do ERP cujo código ainda não está na planilha. Nada que já existe é lido para escrita.
var vendedoresCad = pegarRegistros($node["Vendedores"].json);
var novas = [];
var vistos = {};
vendedoresCad.forEach(function (v) {
  var chave = chaveCodigo(v.codigo);
  if (chave === "" || jaNaPlanilha[chave] || vistos[chave]) return;
  vistos[chave] = true;
  novas.push({
    codigo: String(v.codigo).trim(),
    nome: decodificarEntidadesHtml(v.nome),
    meta: META_INICIAL
  });
});

return [{
  json: {
    total: novas.length,
    jaExistentes: Object.keys(jaNaPlanilha).length,
    novas: novas
  }
}];
